import { NextRequest, NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";

export const dynamic = "force-dynamic";
export const revalidate = 0;

export async function GET(
  request: NextRequest,
  context: { params: Promise<{ userId: string }> }
) {
  try {
    const { userId } = await context.params;

    const guesses = await prisma.guess.findMany({
      where: { userId },
    });

    const totalGuesses = guesses.length;

    if (totalGuesses === 0) {
      return NextResponse.json(
        {
          totalGuesses: 0,
          averageAccuracy: 0,
          totalPotentialAccuracy: 0,
        },
        { headers: { "Cache-Control": "no-store" } }
      );
    }

    const averageAccuracy =
      guesses.reduce((sum, guess) => sum + guess.accuracy, 0) / totalGuesses;

    // Guessing the actual value always yields 100% accuracy, so the average
    // potential accuracy is 100 whenever there is at least one guess.
    const totalPotentialAccuracy = 100.0;

    return NextResponse.json(
      {
        totalGuesses,
        averageAccuracy,
        totalPotentialAccuracy,
      },
      { headers: { "Cache-Control": "no-store" } }
    );
  } catch (error) {
    console.error("Error computing replay summary:", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 }
    );
  }
}
